    return 20

def sum_of_digits(arr):
    sum = 0
    for i in arr:
        sum += sum_of_digits_of(i)
    return sum

def sum_of_digits_of(n):
    sum = 0
    while n:
        sum += n % 10
        n //= 10
    return sum

def find_lists(tuples):
    count = 0
    for item in tuples:
        if type(item) == list:
            count += 1
    return count

def find_Element(arr, rot, index, n):
    for i in range(len(rot)):
        if rot[i][0] == index:
            index = rot[i][1]
    return arr[index]

def is_majority(arr, n, x):
    count = 0
    for i in range(n):
        if arr[i] == x:
            count += 1
    if count > n // 2:
        return True
    return False

