def remove_elements(list1, list2):
    result = [x for x in list1 if x not in list2]
    return result

def find_Element(arr, rotations, index, k):
    for i in range(k):
        temp = arr[0]
        for j in range(len(arr) - 1):
            arr[j] = arr[j + 1]
        arr[len(arr) - 1] = temp
    return arr[index]

def is_undulating(n):
    # Convert the number to a string
    n_str = str(n)

    # Check if the number has at least 3 digits
    if len(n_str) < 3:
        return False

    # Iterate through the digits of the number
    for i in range(len(n_str) - 2):
        # Check if the current digit is equal to either the previous or next digit
        if n_str[i] == n_str[i+1] == n_str[i+2]:
            return False

    # If all digits pass the check, the number is undulating
    return True

def rearrange_bigger(n):
    n = list(str(n))
    i = len(n) - 2
    while i >= 0 and n[i] >= n[i + 1]:
        i -= 1
    if i < 0:
        return -1
    j = len(n) - 1
    while n[j] <= n[i]:
        j -= 1
    n[i], n[j] = n[j], n[i]
    n[i + 1:] = n[i + 1:][::-1]
    return int(''.join(n))

